"""Build per-dataset provenance without changing election results or inferring crosswalks."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];DIST=ROOT/'dist'
def read(path):return json.loads(path.read_text(encoding='utf-8'))
def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest()
meta=read(DIST/'metadata.json');catalog=read(DIST/'archive-catalog.json');datasets=[]
for entry in catalog['entries']:
 path=DIST/'archive'/(entry['id']+'.json')
 datasets.append({'dataset_id':'archive:'+entry['id'],'election_id':entry.get('election_date') or str(entry['year'])+':'+entry['office'],'geography_level':'original_electoral_unit','asset':str(path.relative_to(DIST)).replace('\\','/'),'asset_sha256':digest(path),'source':{'authority':'中央選舉委員會','files':entry['sources'],'downloaded_at':None},'boundary':None,'comparability':{'grade':'D','reason':'保留原始區劃代碼，未建立跨屆地理對應。','direct_difference_allowed':False},'verification_status':{'arithmetic_verified':entry['verifiedContests'],'contests':entry['contests'],'issues':entry['issues']}})
for file,kind in [('history-counties.json','president'),('history-party-list.json','legislator-list'),('history-mayors.json','mayor')]:
 asset=read(DIST/file)
 for election in asset['elections']:
  datasets.append({'dataset_id':kind+':'+str(election['year'])+':county','election_id':kind+':'+str(election['year']),'geography_level':'harmonized_whole_county','asset':file,'asset_sha256':digest(DIST/file),'source':{'authority':'中央選舉委員會','files':election['sourceSHA256'],'directory':election['sourceDirectory'],'downloaded_at':None},'boundary':{'boundary_version':'whole-unit administrative lineage','geometry_sha256':digest(DIST/'towns.json'),'method':asset['derived_method']},'comparability':{'grade':'B','reason':'整縣市無損聚合後同一統計範圍；未提名及缺資料保持NA。','direct_difference_allowed':True},'verification_status':'raw_votes_and_denominators_reconciled'})
for folder,kind in [('villages','president'),('legislator-villages','legislator')]:
 for path in sorted((DIST/folder).glob('*.json')):
  asset=read(path);geo=asset.get('features');geometry_hash=hashlib.sha256(json.dumps([f['geometry'] for f in geo],sort_keys=True,separators=(',',':')).encode()).hexdigest() if geo is not None else None
  source_entries=[source for e in catalog['entries'] if e['year']==2024 and (('總統' in e['office']) if kind=='president' else e['office']=='立法委員（區域）') for source in e['sources']]
  datasets.append({'dataset_id':kind+':2024:village:'+path.stem,'election_id':kind+':2024','geography_level':'village_and_special_statistical_units','asset':folder+'/'+path.name,'asset_sha256':digest(path),'source':{'authority':'中央選舉委員會','files':source_entries,'downloaded_at':None},'boundary':{'boundary_version':meta['boundary_version']['village'],'geometry_sha256':geometry_hash if geo is not None else digest(DIST/'villages'/(asset['metadata']['county']+'.json')),'geometry_asset':folder+'/'+path.name if geo is not None else 'villages/'+asset['metadata']['county']+'.json','method':asset['metadata'].get('method',meta['derived_method'])},'comparability':{'grade':'D','reason':'2024單屆可查；跨屆村里尚需經核驗的crosswalk。','direct_difference_allowed':False},'verification_status':'7738_units_reconciled; special_units_list_only'})
for name,election,level in [('data.json','president:2024 + legislator:2024','county_town_and_regional_district'),('parliament.json','legislator:2024','seat'),('districts-2024.json','legislator:2024','derived_regional_district')]:
 datasets.append({'dataset_id':name.removesuffix('.json'),'election_id':election,'geography_level':level,'asset':name,'asset_sha256':digest(DIST/name),'source':{'authority':'中央選舉委員會','catalog':'archive-catalog.json','downloaded_at':None},'boundary':{'boundary_version':meta['boundary_version'],'geometry_sha256':digest(DIST/('districts-2024.json' if name.startswith('districts') else 'towns.json'))} if name!='parliament.json' else None,'comparability':{'grade':'D','reason':'本屆結果，歷史直接差值尚未核驗。','direct_difference_allowed':False},'verification_status':meta['verification_status']})
registry={'schema_version':1,'data_updated_at':meta['data_updated_at'],'lineage_compiled_at':'2026-11-04','downloaded_at_note':'原始下載時間未留存者為null，不以整理時間代替。','grades':{'A':'已核驗同一邊界','B':'整單位無損聚合後同範圍','C':'估計crosswalk；不開放直接差值','D':'未核驗／不可比；禁止直接差值'},'datasets':datasets}
(DIST/'dataset-registry.json').write_text(json.dumps(registry,ensure_ascii=False,separators=(',',':')),encoding='utf-8')
(DIST/'boundary-registry.json').write_text(json.dumps({'schema_version':1,'boundaries':[{'id':key,'version':version,'asset':'districts-2024.json' if key=='district' else 'towns.json' if key=='administrative' else 'villages/{county}.json','verification':'derived_not_legal_survey' if key=='district' else 'single_election_visualization','historical_direct_difference_allowed':False} for key,version in meta['boundary_version'].items()]},ensure_ascii=False,indent=2),encoding='utf-8')
(DIST/'crosswalk-registry.json').write_text(json.dumps({'schema_version':1,'rules':[{'from':'pre2010 Taichung/Tainan/Kaohsiung county+city','to':'post2010 whole city','grade':'B','method':'sum raw votes, cast and eligible before computing ratios','source':'https://www.moi.gov.tw/News_toggle3.aspx?n=174&sms=9015'},{'from':'historical town/village/regional district','to':'current geometry','grade':'D','method':None,'direct_difference_allowed':False}]},ensure_ascii=False,indent=2),encoding='utf-8')
print('Dataset registry:',len(datasets),'records; source hashes preserved; no inferred crosswalks')
